export const STORAGE_SERVICE = Symbol('STORAGE_SERVICE');

export type ImageContentType = 'image/jpeg' | 'image/png' | 'image/webp';

export interface StoredFile {
  key: string;
}

export interface StorageService {
  /**
   * Stores the content and returns a key generated by the storage system.
   * It does not use the original name provided by the client.
   */

  saveProfilePicture(
    userId: string,
    content: Buffer,
    contentType: ImageContentType,
  ): Promise<StoredFile>;

  /**
   * Deletes a file managed by this storage.
   * The implementation must reject keys that fall outside its scope.
   */
  deleteProfilePicture(key: string): Promise<void>;

  saveProfileBanner(
    userId: string,
    content: Buffer,
    contentType: ImageContentType,
  ): Promise<StoredFile>;

  deleteProfileBanner(key: string): Promise<void>;
}
